"""Pydantic schemas for normalized tool-calling conversations."""

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field


class DatasetModel(BaseModel):
    """Base schema for normalized dataset records."""

    model_config = ConfigDict(extra="forbid")


class FunctionCall(DatasetModel):
    """Function invocation generated by the assistant."""

    name: str = Field(min_length=1)
    arguments: dict[str, Any] = Field(default_factory=dict)


class ToolCall(DatasetModel):
    """Assistant tool call."""

    id: str | None = None
    type: Literal["function"] = "function"
    function: FunctionCall


class ToolSpecification(DatasetModel):
    """Specification of an available function."""

    name: str = Field(min_length=1)
    description: str | None = None
    parameters: dict[str, Any]


class ToolDefinition(DatasetModel):
    """Tool exposed to the language model."""

    type: Literal["function"] = "function"
    function: ToolSpecification


class Message(DatasetModel):
    """One message in a tool-calling conversation."""

    role: Literal["system", "user", "assistant", "tool"]
    content: str | None = None

    tool_calls: list[ToolCall] = Field(default_factory=list)
    tool_call_id: str | None = None
    name: str | None = None


class Conversation(DatasetModel):
    """Validated conversation and its available tools."""

    messages: list[Message] = Field(min_length=2)
    tools: list[ToolDefinition] = Field(default_factory=list)
    meta: dict[str, Any] = Field(default_factory=dict)
